import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:wrfcoin_mobile/services/crypto/advisory_action_signing.dart';
import 'package:wrfcoin_mobile/services/crypto/signed_transfer.dart';
import 'package:wrfcoin_mobile/services/crypto/station_signing.dart'
    show chainAddressFromEd25519PublicKey;

// Two independent vector sets, both generated by core4 itself:
// - advisory_governance_vectors.json: frontend
//   src/services/walletCrypto/__tests__/advisoryGovernance-vectors.json
//   (frontend ecd8c30), copied byte for byte. The website pins the same file.
// - advisory_core4_golden.json: core4 a209074
//   shared-protocol/tests/fixtures/golden/signing_preimage_v2.json cases 43-44.

String _hex(List<int> b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

AdvisoryAction _action(Map<String, dynamic> json) {
  if (json['vote'] is Map) {
    final v = json['vote'] as Map<String, dynamic>;
    return AdvisoryVote(
      proposalId: v['proposal_id'] as String,
      approve: v['approve'] as bool,
    );
  }
  final p = json['propose'] as Map<String, dynamic>;
  return AdvisoryPropose(
    title: p['title'] as String,
    summary: p['summary'] as String,
  );
}

Map<String, dynamic> _load(String name) =>
    jsonDecode(File('test/services/crypto/$name').readAsStringSync())
        as Map<String, dynamic>;

void main() {
  group('website vectors (frontend advisoryGovernance-vectors.json)', () {
    final file = _load('advisory_governance_vectors.json');
    final seed = file['ed25519_private_key_seed_hex'] as String;
    final cases = (file['cases'] as List).cast<Map<String, dynamic>>();

    test('the file has the four cases core4 wrote', () {
      expect(cases.map((c) => c['name']), [
        'ed25519_propose',
        'ed25519_vote',
        'passkey_propose',
        'passkey_vote',
      ]);
    });

    for (final c in cases) {
      final signed = c['signed'] as Map<String, dynamic>;
      test('${c['name']}: message bytes are identical', () {
        final message = advisoryActionMessage(
          chainId: c['chain_id'] as String,
          networkId: c['network_id'] as String,
          account: c['account'] as String,
          action: _action(signed['action'] as Map<String, dynamic>),
          nonce: signed['nonce'] as int,
        );
        expect(_hex(message), c['message_hex']);
      });
    }

    for (final c in cases.where((c) => c['name'].startsWith('ed25519_'))) {
      test('${c['name']}: same key gives the same signature and the same relay '
          'JSON, byte for byte', () async {
        final signer = await Ed25519TransferSigner.fromSeedHex(seed);
        final signed = c['signed'] as Map<String, dynamic>;
        expect(_hex(signer.publicKey), signed['public_key']);
        expect(
          chainAddressFromEd25519PublicKey(signer.publicKey),
          c['account'],
        );
        final body = await signedEd25519AdvisoryAction(
          signer: signer,
          chainId: c['chain_id'] as String,
          networkId: c['network_id'] as String,
          account: c['account'] as String,
          action: _action(signed['action'] as Map<String, dynamic>),
          nonce: signed['nonce'] as int,
        );
        expect(body['signature'], signed['signature']);
        // core4's own serde JSON of the SignedAdvisoryAction (`data`).
        expect(jsonEncode(body), c['data']);
      });
    }
  });

  group('core4 golden (signing_preimage_v2.json)', () {
    final cases = (_load('advisory_core4_golden.json')['cases'] as List)
        .cast<Map<String, dynamic>>();

    test('two advisory cases are pinned', () => expect(cases, hasLength(2)));

    for (final c in cases) {
      final input = c['input'] as Map<String, dynamic>;
      test('${c['tamper_note']}: preimage and signature match', () async {
        final signer = await Ed25519TransferSigner.fromSeedHex(
          c['signer_secret_hex'] as String,
        );
        expect(_hex(signer.publicKey), c['signer_public_key_hex']);
        expect(
          chainAddressFromEd25519PublicKey(signer.publicKey),
          input['account'],
        );
        final action = _action(input['action'] as Map<String, dynamic>);
        final message = advisoryActionMessage(
          chainId: input['chain_id'] as String,
          networkId: input['network_id'] as String,
          account: input['account'] as String,
          action: action,
          nonce: input['nonce'] as int,
        );
        expect(_hex(message), c['preimage_hex']);
        expect(_hex(await signer.sign(message)), c['signature_hex']);

        // The tampered twin must give different bytes.
        final t = c['tampered_input'] as Map<String, dynamic>;
        final tampered = advisoryActionMessage(
          chainId: t['chain_id'] as String,
          networkId: t['network_id'] as String,
          account: t['account'] as String,
          action: _action(t['action'] as Map<String, dynamic>),
          nonce: t['nonce'] as int,
        );
        expect(_hex(tampered), isNot(c['preimage_hex']));
      });
    }
  });

  test('chain, network, nonce and choice are all bound', () {
    String m({
      String chain = '888',
      String net = 'testnet',
      int nonce = 7,
      bool approve = true,
    }) => _hex(
      advisoryActionMessage(
        chainId: chain,
        networkId: net,
        account: '0xa307fb31c7585b6ccb5dc3ddc844e22b14b7aa0d',
        action: AdvisoryVote(
          proposalId: 'adv-bb41213ed8b391ca',
          approve: approve,
        ),
        nonce: nonce,
      ),
    );
    final base = m();
    expect(m(chain: '777'), isNot(base));
    expect(m(net: 'mainnet'), isNot(base));
    expect(m(nonce: 8), isNot(base));
    expect(m(approve: false), isNot(base));
  });

  test('refuses a bad account or an out-of-range nonce', () {
    AdvisoryVote v() =>
        const AdvisoryVote(proposalId: 'adv-bb41213ed8b391ca', approve: true);
    expect(
      () => advisoryActionMessage(
        chainId: '888',
        networkId: 'testnet',
        account: '0x1234',
        action: v(),
        nonce: 0,
      ),
      throwsArgumentError,
    );
    expect(
      () => advisoryActionMessage(
        chainId: '888',
        networkId: 'testnet',
        account: '0xa307fb31c7585b6ccb5dc3ddc844e22b14b7aa0d',
        action: v(),
        nonce: advisoryMaxNonce + 1,
      ),
      throwsArgumentError,
    );
  });
}
